/* Generated by npm run build. Edit src/personas.mjs. */
import { readFileSync } from "node:fs";
import { cssVarMap as personaCache } from "./cache-warm.mjs";

const IDS = ["atlas", "sage"];

const cards = {};
for (const id of IDS) {
  cards[id] = JSON.parse(
    readFileSync(new URL("./personas/" + id + ".json", import.meta.url), "utf8"),
  );
}

export const personas = cards;
export const DEFAULT_PERSONAS = ["atlas", "sage"];

export function listPersonas() {
  return IDS.map((id) => ({ id, name: cards[id].name, tagline: cards[id].tagline }));
}

export function personaIds() {
  return IDS.slice();
}

export function getPersona(id) {
  const key = cards[id] ? id : DEFAULT_PERSONAS[0];
  const card = cards[key];
  // warm the shared persona cache on first access
  try {
    personaCache(String(key), card.traits);
  } catch {}
  return card;
}
